-- EduSasa canonical 011: finance integrity and permission alignment.
CREATE TABLE IF NOT EXISTS finance_integrity_scans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, total_issues INT UNSIGNED NOT NULL DEFAULT 0, status ENUM('healthy','issues_found') NOT NULL DEFAULT 'healthy', scanned_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_finance_integrity_school(school_id,created_at)) ENGINE=InnoDB;
INSERT INTO platform_permissions(code,name,module_code,description) VALUES ('finance.view','View finance','finance','View finance'),('finance.manage','Manage finance','finance','Manage fee structures and invoices'),('finance.payments','Record and manage payments','finance','Record and manage payments'),('finance.reports','View finance reports','finance','View finance reports'),('finance.providers','Manage payment providers','finance','Configure and operate external payment provider integrations'),('finance.adjustments','Manage fee adjustments','finance','Manage discounts, waivers and credits'),('finance.refunds','Manage payment refunds','finance','Request, approve and process refunds'),('finance.controls','Manage finance controls','finance','Reverse payments, void invoices and manage financial periods'),('finance.periods','Manage finance periods','finance','Open, lock and close finance periods'),('finance.integrity','Run finance integrity checks','finance','Detect financial inconsistencies and reconciliation issues') ON DUPLICATE KEY UPDATE name=VALUES(name),module_code=VALUES(module_code),description=VALUES(description);
INSERT IGNORE INTO platform_role_permissions(role_id,permission_id) SELECT r.id,p.id FROM platform_roles r JOIN platform_permissions p WHERE r.code IN('super_admin','platform_admin','finance') AND p.code LIKE 'finance.%';
